def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n >= 98:
        return 'D'

    total_opp_def = 0
    for _, o in history:
        if o == 'D':
            total_opp_def += 1
    rate = total_opp_def / n

    recent_len = 10 if n >= 10 else n
    recent_opp_def = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    last_opp = history[-1][1]

    if rate > 0.6 or recent_opp_def >= 6:
        return 'D'

    if n >= 4:
        opp_last4 = (history[-4][1], history[-3][1], history[-2][1], history[-1][1])
        if opp_last4 == ('D', 'C', 'D', 'C') or opp_last4 == ('C', 'D', 'C', 'D'):
            return 'D'

    if n >= 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'

    if last_opp == 'D':
        if rate > 0.3 or rng.random() < 0.7:
            return 'D'
        else:
            return 'C'

    return 'C'
